def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")
        if ttl <= 0:
            raise ValueError("ttl must be positive")

        cache = OrderedDict()
        cache_size = 0

        def _update_wrapper(wrapper, func):
            wrapper.__name__ = func.__name__
            wrapper.__doc__ = func.__doc__
            return wrapper

        def _check_ttl(key, value):
            if timer() - value['timestamp'] > ttl:
                del cache[key]
                return False
            return True

        def _put(key, value):
            if key in cache:
                if not _check_ttl(key, value):
                    return False
                del cache[key]
            if cache_size >= maxsize:
                cache.popitem(last=False)
            cache[key] = value
            cache_size += 1
            return True

        def _get(key):
            if key in cache:
                if not _check_ttl(key, cache[key]):
                    return None
                return cache[key]['value']
            return None

        def _clear():
            cache.clear()
            cache_size = 0

        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            if key in cache:
                return cache[key]
            value = func(*args, **kwargs)
            if _put(key, {'value': value, 'timestamp': timer()}):
                return value
            return None

        return _update_wrapper(wrapper, func)
    return decorator

