class WAPIResponsePage:
    def __init__(self, response: List, max_results: int):
        self.response = response
        self.max_results = max_results
        self.current_page = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.current_page * self.max_results >= len(self.response):
            raise StopIteration
        page = self.response[self.current_page * self.max_results : (self.current_page + 1) * self.max_results]
        self.current_page += 1
        return page

def _dictsum(dicts):
